        # scalar/array/object.  Since the main helpers are already written to
        # return nested values, we can delegate directly.
        if text is not None:
            # Validate BOM explicitly: if present, it is invalid.
            if text.startswith("\ufeff"):
                raise ValueError("invalid character")

